        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    for r, row in enumerate(grid):
        # Horizontal colored stripe, contiguous from the left edge, followed by background.
        color = row[0]
        if color == bg:
            continue
        c = 0
        while c < w and row[c] == color:
            c += 1
        if 0 < c < w and all(v == bg for v in row[c:]):
            out[r][c] = 1
    return out
