 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # Repeated row-patterns may have some background cells where the
    # corresponding cells in another copy are colored. Mark those omissions.
    for i in range(h):
        if all(v == bg for v in grid[i]):
            continue
        for j in range(i + 1, h):
            if all(v == bg for v in grid[j]):
                continue
            diffs = []
            compatible = True
            for c in range(w):
                a, b = grid[i][c], grid[j][c]
                if a == b:
                    continue
                if a == bg:
                    diffs.append((i, c))
                elif b == bg:
                    diffs.append((j, c))
                else:
                    compatible = False
                    break
            # Only treat close copies as one repeated pattern, not unrelated rows.
            if compatible and diffs and w - len(diffs) >= w // 2:
                for r, c in diffs:
                    out[r][c] = 1
    return out
